total = 0; cm = ru = di = 0
for cid in IDS:
    p = os.path.join(OUT, cid + ".json")
    o = json.load(open(p, encoding="utf-8"))
    assert o["case_id"] == cid
    assert set(o.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, o.keys()
    assert isinstance(o["confidence"], (int, float)) and 0 <= o["confidence"] <= 1
    t = o["trigger"]
    assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}, t.keys()
    assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    assert isinstance(t["reason"], str)
    assert "【原始结果】" in o["prediction_text"] and "【倾向判断】" in o["prediction_text"]
    total += os.path.getsize(p); cm += t["changed_main"]; ru += t["reserve_used"]; di += t["disputed"]
print(f"OK written=47 total_bytes={total} changed_main={cm} reserve_used={ru} disputed={di}")
